contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        address admin = address(this);
        vm.startPrank(admin);
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, _owner));
        vm.stopPrank();
        bool returnedSuccess = ok && abi.decode(ret, (bool));
        assertTrue(returnedSuccess);
    }
}
